RATE_BY_CODE = {r['code']:r for r in RATES}

def eligible(row, track_type):
    return row['track'] == {1:'S',2:'D',3:'E'}[track_type]

def estimate(counts, track_type):
    result=[]
    for code, qty in counts.items():
        row=RATE_BY_CODE[code]
        if not eligible(row,track_type): raise ValueError(f'정거장 선로형식 불일치: {code}')
        qty=Decimal(str(qty))
        if not qty.is_finite() or qty<=0 or qty!=qty.to_integral_value(): raise ValueError(f'정거장 개소수 오류: {code}')
        price=Decimal(row['price_krw'])
        result.append({'code':code,'name':f"{row['structure']} / {row['service']} / {row['platform']} / {('일반부' if row['region']=='RURAL' else '도시부')}", 'quantity':qty,'unit_price':price,'amount':price*qty, 'basis':'KDI 2019 표 Ⅲ-81 / 보고서 p.114 / 2019년 기준 / 승강장 길이 210m 기준 / 제비율 포함·VAT 제외 / 사용자 입력'})
    return result

def add_sheet(workbook, records):
    from openpyxl.styles import Font, PatternFill
    ws=workbook.create_sheet('노반정거장개략')
    ws.append(['공종','단가코드','적용조건','수량','단위','적용단가(원/개소)','금액(원)','단가출처'])
    for r in records:
        ws.append(['정거장',r['code'],r['name'],int(r['quantity']),'개소',int(r['unit_price']),int(r['amount']),r['basis']])
    ws.append(['합계','','','', '', '',int(sum((r['amount'] for r in records),Decimal(0))), '노반 D5 산정표와 별도 · 총사업비 합산 시 중복 여부 검토'])
    ws.freeze_panes='A2'
    for c in ws[1]: c.font=Font(bold=True,color='FFFFFF');c.fill=PatternFill('solid',fgColor='17365D')
    for col,w in {'A':12,'B':42,'C':60,'D':12,'E':12,'F':24,'G':25,'H':90}.items():ws.column_dimensions[col].width=w
    for line in ws.iter_rows(min_row=2):
        for c in line[5:7]:c.number_format='#,##0'
    return ws
